/**
 * The kinds of identifier a product can be matched on, in descending order of how much they
 * prove. A GTIN identifies the article worldwide; a source id identifies it only within the one
 * system it came from, which is why that one carries a domain.
 */
export type ProductIdentifierType =
  | 'EAN'
  | 'GTIN'
  | 'MPN'
  | 'SOURCE_ID'
  | 'UPC';

/**
 * Where a product sits between arriving and being sellable.
 *
 * Stored by name rather than by number: these values appear in raw SQL in phase 3's storefront
 * views and in the check constraint, where a bare 2 says nothing to anyone reading it.
 */
export type ProductStatus =
  | 'ACTIVE'
  | 'DEACTIVATED'
  | 'DRAFT';

